import '../../models/dcc/dcc_dmr_request.dart';
import '../../models/dcc/dcc_document.dart';
import '../../models/dcc/dcc_master_data.dart';
import 'dcc_api_client.dart';
import 'dcc_document_service.dart';
import 'dcc_storage_service.dart';
import 'dcc_session.dart';
import 'dcc_master_data_service.dart';
class DccDmrService {
 static const String tableName='dcc_dmr_requests';
 static Map<String,dynamic> _toRow(DccDmrRequest r)=>{'id':r.id,'document_id':r.documentId,'document_no':r.documentNo,'document_name':r.documentName,'document_type':r.documentType,'department':r.department,'requested_by_name':r.requestedByName,'requested_by_email':r.requestedByEmail,'hod_name':r.hodName,'hod_email':r.hodEmail,'current_revision':r.currentRevision,'request_reason':r.requestReason,'status':r.status,'rejection_reason':r.rejectionReason,'created_date':r.createdDate,'hod_action_date':r.hodActionDate,'dcc_action_date':r.dccActionDate,'source_file_path':r.sourceFilePath,'source_file_name':r.sourceFileName,'revised_file_path':r.revisedFilePath,'revised_file_name':r.revisedFileName,'revised_submitted_date':r.revisedSubmittedDate,'revised_rejection_reason':r.revisedRejectionReason,'modification_access_granted':r.modificationAccessGranted,'updated_at':DateTime.now().toIso8601String()};
 static DccDmrRequest _from(dynamic v){final m=Map<String,dynamic>.from(v as Map);return DccDmrRequest(id:m['id']?.toString()??'',documentId:m['document_id']?.toString()??'',documentNo:m['document_no']?.toString()??'',documentName:m['document_name']?.toString()??'',documentType:m['document_type']?.toString()??'',department:m['department']?.toString()??'',requestedByName:m['requested_by_name']?.toString()??'',requestedByEmail:m['requested_by_email']?.toString()??'',hodName:m['hod_name']?.toString()??'',hodEmail:m['hod_email']?.toString()??'',currentRevision:int.tryParse(m['current_revision']?.toString()??'')??0,requestReason:m['request_reason']?.toString()??'',status:m['status']?.toString()??'PENDING_HOD',rejectionReason:m['rejection_reason']?.toString()??'',createdDate:m['created_date']?.toString()??'',hodActionDate:m['hod_action_date']?.toString()??'',dccActionDate:m['dcc_action_date']?.toString()??'',sourceFilePath:m['source_file_path']?.toString()??'',sourceFileName:m['source_file_name']?.toString()??'',revisedFilePath:m['revised_file_path']?.toString()??'',revisedFileName:m['revised_file_name']?.toString()??'',revisedSubmittedDate:m['revised_submitted_date']?.toString()??'',revisedRejectionReason:m['revised_rejection_reason']?.toString()??'',modificationAccessGranted:m['modification_access_granted']==true);}
 static Future<void> addRequest(DccDmrRequest r) async=>DccApiClient.post('/dmr-requests',body:{'data':_toRow(r)});
 static Future<List<DccDmrRequest>> getRequests() async=>(await DccApiClient.get('/dmr-requests') as List).map(_from).toList();
 static Future<List<DccDmrRequest>> getRequestsByUser(String email) async=>(await DccApiClient.get('/dmr-requests') as List).map(_from).where((r)=>r.requestedByEmail.toLowerCase()==email.trim().toLowerCase()).toList();
 static Future<List<DccDmrRequest>> getRequestsForHod(String email) async=>(await DccApiClient.get('/dmr-requests') as List).map(_from).where((r)=>r.hodEmail.toLowerCase()==email.trim().toLowerCase()).toList();
 static Future<List<DccDmrRequest>> getPendingHodRequests(String email) async=>(await getRequestsForHod(email)).where((r)=>r.status=='PENDING_HOD').toList();
 static Future<List<DccDmrRequest>> getPendingDccRequests() async=>(await getRequests()).where((r)=>['PENDING_DCC','PENDING_DCC_REVIEW'].contains(r.status)).toList();
 static Future<List<DccDmrRequest>> getRequestsWithEditAccess(String email) async=>(await getRequestsByUser(email)).where((r)=>r.modificationAccessGranted&&['EDIT_ACCESS_GRANTED','PENDING_DCC_REVIEW'].contains(r.status)).toList();
 static Future<List<DccDmrRequest>> getPendingDccReviewRequests() async=>(await getRequests()).where((r)=>r.status=='PENDING_DCC_REVIEW').toList();
 static Future<DccDmrRequest?> getRequestById(String id) async {try{return _from(await DccApiClient.get('/dmr-requests/${Uri.encodeComponent(id)}'));}catch(_){return null;}}
 static Future<void> updateRequest(DccDmrRequest r) async=>DccApiClient.patch('/dmr-requests/${Uri.encodeComponent(r.id)}',body:{'data':_toRow(r)});
 static Future<void> deleteRequest(String id) async=>DccApiClient.delete('/dmr-requests/${Uri.encodeComponent(id)}');
 static Future<void> acceptRevisedDocument(DccDmrRequest request,String dccName) async {final latest=await getRequestById(request.id);if(latest==null||latest.status!='PENDING_DCC_REVIEW')throw Exception('This DMR has already been processed.');if(latest.revisedFilePath.trim().isEmpty)throw Exception('Revised file is not available.');final doc=await DccDocumentService.getDocumentById(latest.documentId);if(doc==null)throw Exception('Original DCC document could not be found.');final master=await DccMasterDataService.getByDocumentNo(latest.documentNo);final revision=((master?.revision??latest.currentRevision)>latest.currentRevision?(master?.revision??latest.currentRevision):latest.currentRevision)+1;final filename=latest.revisedFileName.trim().isNotEmpty?latest.revisedFileName:doc.releasedPdfName;final path=await DccStorageService.promoteRevisedToReleased(revisedPath:latest.revisedFilePath,documentId:doc.id,revision:revision,originalFileName:filename);final newDoc=DccDocument(id:'${doc.id}_REV$revision',documentNo:doc.documentNo,documentName:doc.documentName,documentType:doc.documentType,department:doc.department,candidateName:doc.candidateName,employeeId:doc.employeeId,folderName:doc.folderName,attachmentPath:doc.attachmentPath,attachmentName:doc.attachmentName,createdByName:doc.createdByName,createdByEmail:doc.createdByEmail,hodName:doc.hodName,hodEmail:doc.hodEmail,status:'RELEASED',revision:revision,revisionDate:DateTime.now().toIso8601String(),releasedPdfPath:path,releasedPdfName:filename,releasedByName:dccName,releasedByEmail:DccSession.currentUser?.email??'');await DccDocumentService.addDocument(newDoc);await DccMasterDataService.upsertEntry(DccMasterData(documentNo:doc.documentNo,documentName:doc.documentName,documentType:doc.documentType,department:doc.department,candidateName:master?.candidateName.isNotEmpty==true?master!.candidateName:doc.candidateName,candidateEmail:master?.candidateEmail??'',createdByName:master?.createdByName.isNotEmpty==true?master!.createdByName:doc.createdByName,createdByEmail:master?.createdByEmail.isNotEmpty==true?master!.createdByEmail:doc.createdByEmail,revision:revision),manualRevision:revision);final updated=DccDmrRequest(id:latest.id,documentId:newDoc.id,documentNo:latest.documentNo,documentName:latest.documentName,documentType:latest.documentType,department:latest.department,requestedByName:latest.requestedByName,requestedByEmail:latest.requestedByEmail,hodName:latest.hodName,hodEmail:latest.hodEmail,currentRevision:revision,requestReason:latest.requestReason,status:'COMPLETED',createdDate:latest.createdDate,hodActionDate:latest.hodActionDate,dccActionDate:DateTime.now().toIso8601String(),sourceFilePath:latest.sourceFilePath,sourceFileName:latest.sourceFileName,revisedFilePath:latest.revisedFilePath,revisedFileName:latest.revisedFileName,revisedSubmittedDate:latest.revisedSubmittedDate,modificationAccessGranted:false);await updateRequest(updated);}
 static Future<void> rejectRevisedDocument(DccDmrRequest r,String reason,String dccName) async {final upd=DccDmrRequest(id:r.id,documentId:r.documentId,documentNo:r.documentNo,documentName:r.documentName,documentType:r.documentType,department:r.department,requestedByName:r.requestedByName,requestedByEmail:r.requestedByEmail,hodName:r.hodName,hodEmail:r.hodEmail,currentRevision:r.currentRevision,requestReason:r.requestReason,status:'EDIT_ACCESS_GRANTED',rejectionReason:r.rejectionReason,createdDate:r.createdDate,hodActionDate:r.hodActionDate,dccActionDate:DateTime.now().toIso8601String(),sourceFilePath:r.sourceFilePath,sourceFileName:r.sourceFileName,revisedFilePath:r.revisedFilePath,revisedFileName:r.revisedFileName,revisedSubmittedDate:r.revisedSubmittedDate,revisedRejectionReason:reason,modificationAccessGranted:true);await updateRequest(upd);}
}
